@Slf4j
@Service
@RequiredArgsConstructor
public class Xfr60CommandService {

    private final Xfr60Repository orderShipmentRepository;
    private final Xbp24CommandService notificationCommandService;
    private final Xzt63QueryService saleBidQueryService;
    private final Xtw92QueryService orderBidQueryService;
    private final Xms75CommandService warehouseStorageCommandService;
    private final Xwg86 cjTrackingPlaywright;











    @Transactional
    public Xfr60 createOrderShipment(Xhq12 order, String receiverName, String receiverPhone,
                                             String postalCode, String address) {
        log.info("주문 배송 정보 생성 시작: orderId={}, receiverName={}",
                order.getId(), receiverName);

        Xfr60 shipment = Xfr60.builder()
                .order(order)
                .receiverName(receiverName)
                .receiverPhone(receiverPhone)
                .postalCode(postalCode)
                .address(address)
                .status(Xzn53Status.PENDING)
                .build();

        Xfr60 savedShipment = orderShipmentRepository.save(shipment);
        log.info("주문 배송 정보 생성 완료: shipmentId={}, orderId={}",
                savedShipment.getId(), order.getId());

        return savedShipment;
    }







    @Transactional
    public void updateShipmentStatus(Xfr60 shipment, Xzn53Status newStatus) {
        log.info("배송 상태 업데이트: shipmentId={}, currentStatus={}, newStatus={}",
                shipment.getId(), shipment.getStatus(), newStatus);

        try {
            shipment.updateStatus(newStatus);
            orderShipmentRepository.save(shipment);

            log.info("배송 상태 업데이트 완료: shipmentId={}, status={}",
                    shipment.getId(), newStatus);
        } catch (IllegalStateException e) {
            log.error("배송 상태 업데이트 실패: shipmentId={}, error={}",
                    shipment.getId(), e.getMessage(), e);

            throw new Xzn53Exception(
                    Xzn53ErrorCode.INVALID_SHIPMENT_STATUS_TRANSITION,
                    "유효하지 않은 배송 상태 전환입니다: " + e.getMessage(),
                    e
            );
        }
    }






    @Transactional
    public void updateSaleStatusToSold(Long orderId) {
        log.info("판매 상태를 'SOLD'로 변경 시작: orderId={}", orderId);


        Xzt63 saleBid = saleBidQueryService.findByOrderId(orderId);
        if (saleBid != null) {
            Xpj42 sale = saleBid.getSale();
            if (sale != null && sale.getStatus().canTransitionTo(Xpj42Status.SOLD)) {
                log.info("Xpj42 상태 'SOLD'로 변경: saleId={}, sellerId={}",
                        sale.getId(), sale.getSeller().getId());

                sale.updateStatus(Xpj42Status.SOLD);


                if (sale.isWarehouseStorage()) {
                    log.info("창고 보관 상품의 창고 상태 업데이트: saleId={}", sale.getId());
                    warehouseStorageCommandService.updateWarehouseStatusToSold(sale);
                }


                Xjm45 seller = sale.getSeller();
                notificationCommandService.createNotification(
                        seller.getId(),
                        Xrv73.SHOPPING,
                        Xbp24Type.BID,
                        "상품이 성공적으로 판매 완료되었습니다. 판매 ID: " + sale.getId()
                );

                log.info("판매자 알림 생성 완료: sellerId={}, saleId={}",
                        seller.getId(), sale.getId());
            } else {
                log.debug("Xpj42 상태 변경 불가 또는 Sale이 null: saleBidId={}", saleBid.getId());
            }
        } else {
            log.debug("해당 주문과 연결된 SaleBid가 없음: orderId={}", orderId);
        }


        try {
            Xtw92 orderBid = orderBidQueryService.findByOrderId(orderId)
                    .orElseThrow(() -> new IllegalArgumentException("해당 OrderBid를 찾을 수 없습니다: " + orderId));

            if (orderBid != null) {
                Xpj42 sale = orderBid.getSale();
                if (sale != null && sale.getStatus().canTransitionTo(Xpj42Status.SOLD)) {
