    @Transactional
    private void updateOrderAndSaleBidStatusToCompleted(Long orderId) {
        log.info("입찰 상태 COMPLETED로 변경: orderId={}", orderId);

        try {

            Xtw92 orderBid = orderBidQueryService.findByOrderId(orderId)
                    .orElseThrow(() -> new IllegalArgumentException("해당 OrderBid를 찾을 수 없습니다: " + orderId));


            if (orderBid.getStatus() == com.fream.back.domain.m99.entity.Xkh73Status.MATCHED) {
                log.debug("Xtw92 상태 COMPLETED로 변경: orderBidId={}", orderBid.getId());
                orderBid.updateStatus(com.fream.back.domain.m99.entity.Xkh73Status.COMPLETED);
            }


            Xzt63 saleBid = saleBidQueryService.findByOrderId(orderId);
            if (saleBid != null && saleBid.getStatus() == Xkh73Status.MATCHED) {
                log.debug("Xzt63 상태 COMPLETED로 변경: saleBidId={}", saleBid.getId());
                saleBid.updateStatus(Xkh73Status.COMPLETED);
            }

            log.info("입찰 상태 COMPLETED 변경 완료: orderId={}", orderId);

