@Slf4j
@Service
@RequiredArgsConstructor
public class Xmt80CommandService {

    private final Xmt80Repository pointRepository;
    private final Xjm45QueryService userQueryService;




    @Transactional
    public Xmt80Dto.Xmt80Response addPoint(String email, Xmt80Dto.Xnb27Request request) {
        log.info("포인트 적립 시작 - 사용자: {}, 적립액: {}", email, request.getAmount());

        try {

            validateAddPointRequest(request);

            Xjm45 user = userQueryService.findByEmail(email);
            if (user == null) {
                throw new Xgx35Exception(email);
            }

            Xmt80 point = Xmt80.builder()
                    .user(user)
                    .amount(request.getAmount())
                    .remainingAmount(request.getAmount())
                    .reason(request.getReason())
                    .expirationDate(LocalDate.now().plusDays(90))
                    .status(Xmt80Status.AVAILABLE)
                    .build();

            Xmt80 savedPoint = pointRepository.save(point);

            log.info("포인트 적립 완료 - 사용자: {}, 적립액: {}, 포인트 ID: {}",
                    email, request.getAmount(), savedPoint.getId());

            return Xmt80Dto.Xmt80Response.from(savedPoint);
        } catch (Xgx35Exception | Xbz76Exception e) {
            throw e;
        } catch (Exception e) {
            log.error("포인트 적립 중 예상치 못한 오류 발생 - 사용자: {}, 적립액: {}",
                    email, request.getAmount(), e);
            throw new Xbz76Exception("포인트 적립 처리 중 오류가 발생했습니다.");
        }
    }




    @Transactional
    public Xmt80Dto.Xdc63Response usePoint(String email, Xmt80Dto.Xdc63Request request) {
        log.info("포인트 사용 시작 - 사용자: {}, 사용액: {}", email, request.getAmount());

        try {

            validateUsePointRequest(request);

            Xjm45 user = userQueryService.findByEmail(email);
            if (user == null) {
                throw new Xgx35Exception(email);
            }

            int pointsToUse = request.getAmount();


            Integer totalAvailable = pointRepository.getTotalAvailablePoints(user);
            if (totalAvailable == null || totalAvailable < pointsToUse) {
                log.warn("포인트 부족 - 사용자: {}, 필요: {}, 보유: {}",
                        email, pointsToUse, totalAvailable != null ? totalAvailable : 0);
                throw new Xwq96Exception(pointsToUse, totalAvailable != null ? totalAvailable : 0);
            }


            List<Xmt80> availablePoints = pointRepository.findByUserAndStatusOrderByExpirationDateAsc(user, Xmt80Status.AVAILABLE);
            int remainingToUse = pointsToUse;
            int totalUsed = 0;

            for (Xmt80 point : availablePoints) {
                if (remainingToUse <= 0) break;

                Integer usedAmount = point.use(remainingToUse);
                int used = usedAmount != null ? usedAmount : 0;
                remainingToUse -= used;
                totalUsed += used;


                if (used > 0) {
                    point.setReason(request.getReason());
                    pointRepository.save(point);
                }
            }


            Integer remainingTotal = pointRepository.getTotalAvailablePoints(user);
            if (remainingTotal == null) remainingTotal = 0;

            log.info("포인트 사용 완료 - 사용자: {}, 사용액: {}, 남은 포인트: {}",
                    email, totalUsed, remainingTotal);

            return Xmt80Dto.Xdc63Response.builder()
                    .usedPoints(totalUsed)
                    .remainingTotalPoints(remainingTotal)
                    .message("포인트가 성공적으로 사용되었습니다.")
                    .build();
        } catch (Xgx35Exception | Xbz76Exception | Xwq96Exception e) {
            throw e;
        } catch (Exception e) {
            log.error("포인트 사용 중 예상치 못한 오류 발생 - 사용자: {}, 사용액: {}",
                    email, request.getAmount(), e);
            throw new Xwq96Exception("포인트 사용 처리 중 오류가 발생했습니다.");
        }
    }




    @Transactional
    public int expirePoints() {
        log.info("만료 포인트 처리 시작");

        try {
            List<Xmt80> expiredPoints = pointRepository.findByStatusAndExpirationDateBefore(
                    Xmt80Status.AVAILABLE, LocalDate.now());

            for (Xmt80 point : expiredPoints) {
                point.expire();
            }

            log.info("만료 포인트 처리 완료 - 만료된 포인트 수: {}", expiredPoints.size());
            return expiredPoints.size();
        } catch (Exception e) {
            log.error("만료 포인트 처리 중 오류 발생", e);
            return 0;
        }
    }




    private void validateAddPointRequest(Xmt80Dto.Xnb27Request request) {
        if (request == null) {
            throw new Xbz76Exception("포인트 적립 요청 데이터가 없습니다.");
        }

        if (request.getAmount() <= 0) {
            throw new Xbz76Exception(request.getAmount());
        }

        if (request.getAmount() > 1000000) {
            throw new Xbz76Exception("한 번에 적립할 수 있는 포인트는 최대 1,000,000점입니다.");
        }

        if (request.getReason() == null || request.getReason().trim().isEmpty()) {
            throw new Xbz76Exception("포인트 적립 사유를 입력해주세요.");
        }
    }




    private void validateUsePointRequest(Xmt80Dto.Xdc63Request request) {
        if (request == null) {
            throw new Xbz76Exception("포인트 사용 요청 데이터가 없습니다.");
        }

        if (request.getAmount() <= 0) {
            throw new Xbz76Exception(request.getAmount());
        }

        if (request.getReason() == null || request.getReason().trim().isEmpty()) {
            throw new Xbz76Exception("포인트 사용 사유를 입력해주세요.");
        }
    }
